CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY, email VARCHAR(255) NOT NULL, "password" TEXT NOT NULL, created_at TIMESTAMP NOT NULL);
ALTER TABLE users ADD CONSTRAINT users_email_unique UNIQUE (email);
CREATE TABLE IF NOT EXISTS todos (id uuid PRIMARY KEY, user_id uuid NOT NULL, title VARCHAR(500) NOT NULL, done BOOLEAN DEFAULT FALSE NOT NULL, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, CONSTRAINT fk_todos_user_id__id FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE RESTRICT ON UPDATE RESTRICT);